  /* ------------------------------------------------------------------ kinder, truer words (world 3, level 2)
     A harsh thought, and three ways to say it; the first is both kind and true. */
  function F(id, g, harsh, opts, pa) { return tagged({ id: id, g: g, harsh: harsh, options: o(opts) }, pa); }
  P.reframe = [
    F('k01', 1, 'I ruined the whole evening.',
      [['One part of the evening went badly. I can say sorry for that part and still enjoy the rest.', 'Kind and true: it names the real part, and leaves room to put it right.'],
       ['I always ruin everything.', 'That’s harsher, and “always” and “everything” aren’t true.'],
       ['The evening was perfect. Nothing went wrong at all.', 'That’s kind, but it isn’t true. Pretending doesn’t help you put it right.']], '3s'),
    F('k02', 2, 'I’m so behind. Everyone else has it together.',
      [['I’m behind on a few things this week. Tomorrow I can pick the one that matters most.', 'True and kind: a few things, this week, and one small next step.'],
       ['I’m not behind at all. Lists are pointless anyway.', 'It sounds cheerful, but it isn’t quite true, and it won’t help the list.'],
       ['I’m hopeless at life.', 'That’s the harsh thought again, just bigger.']], '1s'),
    F('k03', 2, 'I shouldn’t need a rest. I haven’t done enough to deserve one.',
      [['Rest isn’t a prize. I’m tired, and a break will help me do the next thing.', 'Yes. Rest isn’t something you earn. It’s something you need.'],
       ['Rest is only for people who’ve earned it.', 'That’s the same harsh rule, said more firmly.'],
       ['I never need rest. I can keep going forever.', 'Nobody can, and that’s fine. Everyone’s battery needs topping up.']], '3s'),
    F('k04', 2, 'I had to ask for help, so I must be weak.',
      [['Asking for help is how two people share a load. It took some courage.', 'Yes. Asking clearly is a strength, and it lets someone help you well.'],
       ['I didn’t really need help. I just asked to be polite.', 'That hides the truth. Needing help is normal.'],
       ['Real grown-ups never ask for anything.', 'Everyone needs help sometimes. Saying so is a skill, not a failing.']], '1s'),
    F('k05', 1, 'I forgot the school form again. I’m a useless parent.',
      [['I forgot the form this week. A reminder on the calendar would help me next time.', 'Kind and true: one forgotten form, and a fix for the setup, not a verdict on you.'],
       ['Forms don’t matter anyway.', 'It might feel better, but it isn’t true. The form did matter.'],
       ['I’m the worst parent in the school.', 'That’s a harsh verdict, built from one forgotten form.']], '2s'),
    F('k06', 2, 'I snapped at my friend. I’m a horrible person.',
      [['I snapped because I was running on empty. I can say sorry, and look after my battery.', 'Yes. It owns the snap and notices your state, without a verdict on who you are.'],
       ['It was their fault for asking at a bad time.', 'That moves the blame instead of looking kindly at what happened.'],
       ['I’m always horrible to everyone.', '“Always” and “everyone” make it bigger, not truer.']], '3s'),
    F('k07', 1, 'Nobody ever notices what I do.',
      [['Some of what I do is invisible. I could name it, kindly, so it gets seen.', 'Kind and true: invisible work is real, and naming it is a step you can take.'],
       ['Everyone notices everything I do, all the time.', 'Cheerful, but probably not true, and it hides a real need.'],
       ['Nobody cares about me at all.', 'That’s a much bigger, harsher story than “unnoticed”.']], '5s'),
    F('k08', 3, 'I get upset about tiny things. Something must be wrong with me.',
      [['When my battery is low, small things feel bigger. That’s a sign to rest, not a flaw.', 'Yes. A full tank makes small things feel huge. Reading your state first is kind and true.'],
       ['Tiny things never upset me.', 'That isn’t true, and pretending won’t help you notice your state.'],
       ['I’m just an overly sensitive person.', 'That’s a verdict about yourself. Your state explains more than a label does.']], '3s'),
    F('k09', 2, 'I can’t do anything right.',
      [['This one thing went wrong. I’ve done plenty right today, too.', 'Kind and true: it keeps the one thing its real size.'],
       ['I do everything perfectly.', 'Nobody does. Kindness doesn’t need perfect.'],
       ['I’ll never get anything right.', 'That’s the same harsh thought, stretched into the future.']], '3s'),
    F('k10', 2, 'I said no to my sister. I’m so selfish.',
      [['I said no because my battery is empty this week. A kind no still leaves room to help another time.', 'Yes. Saying no to protect your battery isn’t selfish, and you kept the door open.'],
       ['She shouldn’t have asked in the first place.', 'That turns your guilt into blame. It isn’t kinder, just aimed elsewhere.'],
       ['I’m a terrible sister.', 'A harsh verdict about you, from one honest no.']], '3s'),
    F('k11', 3, 'Our talk went badly. We’re clearly just not compatible.',
      [['We read the same moment differently. We can compare notes on a calmer day.', 'Kind and true: a mix-up runs both ways, and it can be retuned.'],
       ['It went perfectly. There’s nothing to talk about.', 'That isn’t true, and it leaves the mix-up where it is.'],
       ['It was all my fault. I always get it wrong.', 'That’s harsh on you, and a mix-up is rarely one person’s fault.']], '4w'),
    F('k12', 1, 'I’m too tired to do anything useful. What a waste of a day.',
      [['I’m tired today. Resting is useful too, and I can do one small thing if I want.', 'Yes. A tired day is a day for rest, not a waste.'],
       ['I’m not tired. I just need to push harder.', 'Pushing past an empty battery tends to show up later.'],
       ['I waste every day.', 'A harsh story, much bigger than one tired day.']], '3s'),
    F('k13', 2, 'I’m always the one who has to remember everything.',
      [['I’m carrying a lot of the remembering right now. We could share it out on our list.', 'Kind and true: it names the load, and points at a fair fix.'],
       ['I don’t mind remembering everything. It’s nothing.', 'It may not be nothing. Invisible work counts.'],
       ['Nobody else in this house is any use.', 'That’s a verdict on everyone, and it won’t help share the load.']], '1s'),
    F('k14', 3, 'I shouldn’t feel hurt. It was only a small comment.',
      [['It landed hard, and that’s real. I can let it settle, then decide if it needs an answer.', 'Yes. Feelings don’t need permission. Letting them land first is kind.'],
       ['I’m not hurt at all.', 'If you are, pretending won’t help it settle.'],
       ['I’m pathetic for being hurt by that.', 'A harsh verdict on a very normal feeling.']], '4s'),
    F('k15', 1, 'I made a mistake at work. Everyone must think I’m useless.',
      [['I made one mistake, and I can fix it. Everyone makes mistakes sometimes.', 'Kind and true: one mistake, one fix, and the same as everyone.'],
       ['It wasn’t really a mistake.', 'If it was, owning it gently is kinder than pretending.'],
       ['I’ll probably be fired.', 'A big story from one mistake. It isn’t kind, and it probably isn’t true.']], '2s'),
    F('k16', 2, 'I keep putting off that phone call. I’m so lazy.',
      [['The call feels hard, so I keep avoiding it. I could write down my first sentence and call at ten.', 'Yes. Putting things off often means they feel hard, not that you’re lazy. A small step helps.'],
       ['I’ll call when I feel like it. It doesn’t matter.', 'It might matter. A small step helps more than pretending it doesn’t.'],
       ['I’m hopeless. I never do anything.', 'That’s bigger and harsher, and not true.']], '3s'),
    F('k17', 3, 'They didn’t reply to my message. I must have said something wrong.',
      [['They haven’t replied yet. I don’t know why. I can wait, or ask kindly later.', 'Kind and true: it separates what you know from the story you’re adding.'],
       ['They’ve definitely read it and are ignoring me.', 'That’s a story. You don’t know that.'],
       ['I always say the wrong thing.', 'That’s a harsh verdict on you, and there’s no evidence for it.']], '4s'),
    F('k18', 2, 'I’m the only one who ever tries in this friendship.',
      [['Lately I’ve done most of the planning. I could say so kindly, and ask them to plan the next one.', 'Yes. It names the load, and asks for a fairer share.'],
       ['Friendships don’t need anyone to try.', 'Most friendships need a little effort, from both sides.'],
       ['They don’t care about me at all.', 'That’s a big guess about what’s inside them.']], '1w'),
    F('k19', 1, 'I cried in front of my friend. How embarrassing.',
      [['I was having a hard moment, and my friend was there. That’s what friends are for.', 'Kind and true: feelings are normal, and sharing them brings people closer.'],
       ['I didn’t really cry.', 'If you did, there’s nothing to hide.'],
       ['I’ll never be able to face them again.', 'That’s a much bigger story than the moment.']], '4w'),
    F('k20', 3, 'We argue about the same chores every week. We’re a failure.',
      [['The same argument keeps coming back. That’s a sign the setup needs a fix, not that we do.', 'Yes. A repeat is about the setup: an owner, a list, a monthly look-back.'],
       ['Arguing every week is completely normal. Nothing needs to change.', 'Disagreements are normal, but a weekly repeat is a sign something could work better.'],
       ['We should give up.', 'That’s a harsh leap from a chore that keeps slipping.']], '2w'),
    F('k21', 2, 'I felt jealous of my friend’s good news. I’m a bad friend.',
      [['I felt a pang, and I was still happy for them. Both can be true.', 'Kind and true: feelings can be mixed, and you can still turn toward them.'],
       ['I wasn’t jealous at all.', 'If you were, it’s okay. Pretending isn’t needed.'],
       ['I’m a terrible person for feeling that.', 'A harsh verdict on a normal, passing feeling.']], '4s'),
    F('k22', 3, 'I took a break mid-talk. I’m just avoiding hard things.',
      [['I paused because I was wound up, and I said when I’d come back. That’s not avoiding.', 'Yes. A pause with a return time is a promise, not an escape.'],
       ['Breaks mean I never have to finish the talk.', 'That turns a pause into an escape. The return time is the part that matters.'],
       ['I can’t handle anything.', 'That’s a harsh verdict. You handled it by pausing well.']], '3s'),
    F('k23', 2, 'I don’t know how I feel. I must be bad at feelings.',
      [['Some feelings are hard to name. I can start with simple ones: more tired, or more annoyed?', 'Kind and true: finding the word can be hard for anyone, and there are gentle ways in.'],
       ['I always know exactly how I feel.', 'Few people do. It’s fine not to.'],
       ['Something is broken in me.', 'That’s a harsh story. Many people find feelings hard to name.']], '4s')
  ];

